<?php
require_once 'includes/../includes/header.php';
$id=(int)($_GET['id']??0); $stmt=$pdo->prepare('SELECT * FROM restaurants WHERE id=?'); $stmt->execute([$id]); $restaurant=$stmt->fetch(); if(!$restaurant) redirect('restaurants.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['name']??''); $description=trim($_POST['description']??''); $locality=trim($_POST['locality']??''); $address=trim($_POST['address']??''); $cuisine=trim($_POST['cuisine']??''); $latitude=$_POST['latitude']!==''?(float)$_POST['latitude']:null; $longitude=$_POST['longitude']!==''?(float)$_POST['longitude']:null; $phone=trim($_POST['phone']??''); $image=trim($_POST['image']??''); $rating=$_POST['rating']!==''?(float)$_POST['rating']:null; $opening=$_POST['opening_time']?:null; $closing=$_POST['closing_time']?:null; $active=isset($_POST['is_active'])?1:0; if(!$name||!$description||!$locality||!$address||!$cuisine||($image&&!filter_var($image,FILTER_VALIDATE_URL)))$error='Complete the required fields and use a valid image URL.'; else { $update=$pdo->prepare('UPDATE restaurants SET name=?,description=?,locality=?,address=?,latitude=?,longitude=?,phone=?,image=?,cuisine=?,rating=?,opening_time=?,closing_time=?,is_active=? WHERE id=?'); $update->execute([$name,$description,$locality,$address,$latitude,$longitude,$phone,$image,$cuisine,$rating,$opening,$closing,$active,$id]); redirect('restaurants.php'); } }
$page_title='Edit Restaurant';
?>
<div class="form-shell"><h1>Edit restaurant</h1><?php if($error): ?><p class="error"><?=esc($error)?></p><?php endif; ?><form method="post"><label>Name<input name="name" value="<?=esc($restaurant['name'])?>" required></label><label>Description<textarea name="description" required><?=esc($restaurant['description'])?></textarea></label><label>Locality<input name="locality" value="<?=esc($restaurant['locality'])?>" required></label><label>Address<input name="address" value="<?=esc($restaurant['address'])?>" required></label><div class="two-col"><label>Latitude<input name="latitude" type="number" step="any" value="<?=esc($restaurant['latitude'])?>"></label><label>Longitude<input name="longitude" type="number" step="any" value="<?=esc($restaurant['longitude'])?>"></label></div><label>Phone<input name="phone" value="<?=esc($restaurant['phone'])?>"></label><label>Cuisine<input name="cuisine" value="<?=esc($restaurant['cuisine'])?>" required></label><label>Image URL<input name="image" type="url" value="<?=esc($restaurant['image'])?>"></label><div class="two-col"><label>Opening time<input name="opening_time" type="time" value="<?=esc($restaurant['opening_time'])?>"></label><label>Closing time<input name="closing_time" type="time" value="<?=esc($restaurant['closing_time'])?>"></label></div><label>Rating<input name="rating" type="number" min="0" max="5" step="0.1" value="<?=esc($restaurant['rating'])?>"></label><label><input type="checkbox" name="is_active" <?=$restaurant['is_active']?'checked':''?> style="width:auto"> Active</label><div class="form-actions"><button type="submit">Update Restaurant</button> <a class="button secondary" href="restaurants.php">Cancel</a></div></form></div><?php include 'includes/footer.php'; ?>
